using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var openAiClient = new OpenAIClient(apiKey);
IChatClient innerClient = openAiClient.GetChatClient("gpt-4o").AsIChatClient();

var researchTools = new ResearchTools();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Taking notes on key findings as you go
        3. After gathering enough information, reviewing your notes and providing a comprehensive summary

        Always take notes on important findings before moving to the next search.
        When you have enough information, retrieve all notes and write a final summary.
        """),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("Agent is working...\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine($"📝 Total notes taken: {researchTools.NoteCount}");
Console.WriteLine("═══════════════════════════════════════════");

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing 2026"
        : input;
}

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var result = await _http.GetFromJsonAsync<JsonElement>(url);

            var snippets = new List<string>();

            if (result.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                snippets.Add($"Summary: {abstractText}");

            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        snippets.Add(t);
                }
            }

            if (snippets.Count == 0)
                snippets.Add($"No detailed results found for '{query}'. Try a different search query.");

            return string.Join("\n\n", snippets);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("A title or category for this note")] string title,
        [Description("The content of the note")] string content)
    {
        _notes.Add($"[{title}] {content}");
        Console.WriteLine($"  📝 Note taken: {title}");
        return $"Note saved: '{title}'";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  📖 Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

